import { loadFont } from "@remotion/google-fonts/Poppins";
import React from "react";
import { AbsoluteFill, Easing, Img, interpolate, staticFile, useCurrentFrame } from "remotion";

// SOLUTION Consultoria empresarial. Motion vertical de 39 s sobre a locução (ElevenLabs, 37,9 s, entra em 0,15 s).
// Tom sério e institucional: fundo claro e liso, preto do logo e o verde-petróleo do globo; duas cenas em verde cheio
// ("nós fazemos isso por você" e o telefone) para virar a página. Ícones em traço fino, no mesmo desenho do globo.
// O texto entra e fica parado; o movimento contínuo fica na câmera de cada cena e nos objetos.
// Tempos = tempo da palavra na voz; `t` já desconta a entrada da locução.

const { fontFamily: F } = loadFont("normal", { weights: ["400", "500", "600", "700"], subsets: ["latin", "latin-ext"] });

export const SLT_FPS = 30;
const LEAD = 0.15;
export const SLT_FRAMES = Math.round(39.0 * SLT_FPS);

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const BACK = Easing.out(Easing.back(1.5));
const INOUT = Easing.bezier(0.65, 0, 0.35, 1);
const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const pop = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const io = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], { ...cl, easing: INOUT });

const PAPER = "#F4F7F7";
const WHITE = "#FFFFFF";
const INK = "#121414";
const MUTED = "#6B7676";
const LINE = "#DCE5E4";
const TEAL = "#147A74";
const TEAL_D = "#0E5D58";
const TEAL_L = "#E3F1EF";
const RED = "#C8473F";
const SHADOW = "0 30px 70px rgba(14,60,58,0.13), 0 4px 14px rgba(14,60,58,0.07)";

// trocas de cena (tempo da voz, dentro dos silêncios)
const T2 = 6.55, T3 = 9.0, T4 = 14.45, T5 = 21.8, T6 = 27.75, T7 = 33.2;

// texto: entra desfocado com leve escala, assenta e fica parado; sai desfocando no mesmo lugar
const blurIn = (t: number, at: number, out?: number, d = 0.45): React.CSSProperties => {
  const e = k(t, at, d);
  const o = out === undefined ? 0 : lin(t, out, out + 0.2);
  return {
    opacity: Math.min(1, e * 1.6) * (1 - o),
    filter: `blur(${((1 - e) * 16 + o * 14).toFixed(1)}px)`,
    transform: `scale(${(0.9 + 0.1 * e).toFixed(4)})`,
  };
};

type L = [string, number, boolean?];
const Lines: React.FC<{ t: number; items: L[]; size: number; top: number; color?: string; accent?: string; out?: number; weight?: number }> = ({ t, items, size, top, color = INK, accent = TEAL, out, weight = 600 }) => (
  <div style={{ position: "absolute", left: 120, right: 120, top, display: "flex", flexDirection: "column", alignItems: "center" }}>
    {items.map(([w, at, hl], i) => (
      <div key={i} style={{ fontFamily: F, fontWeight: weight, fontSize: size, lineHeight: 1.12, letterSpacing: "-0.03em", whiteSpace: "nowrap", color: hl ? accent : color, ...blurIn(t, at, out) }}>
        {w}
      </div>
    ))}
  </div>
);

// câmera da cena: deriva lenta e contínua, cada cena numa direção
// `hits`: batida curta de aproximação na palavra forte da fala (não é pulso periódico)
const Cam: React.FC<{ t: number; a: number; b: number; from: [number, number, number]; to: [number, number, number]; hits?: number[]; children: React.ReactNode }> = ({ t, a, b, from, to, hits = [], children }) => {
  const p = interpolate(t, [a, b], [0, 1], { ...cl, easing: Easing.bezier(0.33, 0, 0.25, 1) });
  const h = hits.reduce((acc, at) => acc + (t >= at ? 0.05 * Math.exp(-(t - at) * 5) * Math.min(1, (t - at) / 0.06) : 0), 0);
  const s = from[0] + (to[0] - from[0]) * p + h, x = from[1] + (to[1] - from[1]) * p, y = from[2] + (to[2] - from[2]) * p;
  return <AbsoluteFill style={{ transform: `translate(${x.toFixed(1)}px, ${y.toFixed(1)}px) scale(${s.toFixed(4)})` }}>{children}</AbsoluteFill>;
};

// traço que se desenha (pathLength = 1)
const draw = (t: number, a: number, d = 0.6) => {
  const e = interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
  return { strokeDasharray: 1, strokeDashoffset: 1 - e, opacity: e > 0 ? 1 : 0 } as React.CSSProperties;
};
const SW = { fill: "none", strokeLinecap: "round", strokeLinejoin: "round" } as const;

// ───────── 1 · abertura: o empresário, tempo e dinheiro, a licença vencida ─────────
const Abertura: React.FC<{ t: number }> = ({ t }) => {
  const bag = pop(t, 0.05, 0.5);
  const bagOut = lin(t, 1.3, 1.55);
  const clockIn = pop(t, 1.7, 0.5);
  const coinsIn = pop(t, 2.0, 0.5);
  const sceneBOut = io(t, 3.85, 4.15);
  const spin = interpolate(t, [1.7, 4.0], [0, 1], cl);
  const docs = k(t, 4.0, 0.6);
  const stamp = pop(t, 5.6, 0.35);
  return (
    <AbsoluteFill style={{ background: PAPER }}>
      {/* A · Olá, empresário! (a frase ocupa o centro; a pasta entra por baixo) */}
      <Lines t={t} items={[["Olá,", 0.0], ["empresário!", 0.36, true]]} size={150} top={560} out={1.35} />
      <div style={{ position: "absolute", left: 540 - 150, top: 1000, width: 300, height: 260, opacity: bag * (1 - bagOut), transform: `translateY(${((1 - bag) * 160 + bagOut * 40).toFixed(1)}px) rotate(${((1 - bag) * -14).toFixed(1)}deg) scale(${(0.6 + 0.4 * bag).toFixed(3)})` }}>
        <svg viewBox="0 0 300 260" width={300} height={260}>
          <rect x={20} y={70} width={260} height={170} rx={28} stroke={INK} strokeWidth={12} {...SW} />
          <path d="M105 70 V45 a18 18 0 0 1 18 -18 h54 a18 18 0 0 1 18 18 V70" stroke={INK} strokeWidth={12} {...SW} />
          <path d="M20 140 H280" stroke={TEAL} strokeWidth={12} {...SW} />
          <rect x={128} y={122} width={44} height={36} rx={8} fill={TEAL} />
        </svg>
      </div>

      {/* B · tempo e dinheiro indo embora */}
      <Lines t={t} items={[["Não perca mais", 1.59], ["tempo e dinheiro", 2.37, true]]} size={104} top={330} out={3.85} />
      <div style={{ position: "absolute", left: 140, top: 820, width: 380, height: 380, opacity: clockIn * (1 - sceneBOut), transform: `scale(${(0.5 + 0.5 * clockIn - 0.15 * sceneBOut).toFixed(3)}) translateX(${(-sceneBOut * 120).toFixed(1)}px)` }}>
        <svg viewBox="0 0 380 380" width={380} height={380}>
          <circle cx={190} cy={190} r={160} stroke={INK} strokeWidth={14} {...SW} />
          {Array.from({ length: 12 }).map((_, i) => {
            const a = (i / 12) * Math.PI * 2;
            return <path key={i} d={`M${190 + Math.sin(a) * 128} ${190 - Math.cos(a) * 128} L${190 + Math.sin(a) * 140} ${190 - Math.cos(a) * 140}`} stroke={MUTED} strokeWidth={8} {...SW} />;
          })}
          <path d="M190 190 V95" stroke={INK} strokeWidth={14} {...SW} style={{ transform: `rotate(${(spin * 720).toFixed(1)}deg)`, transformOrigin: "190px 190px" }} />
          <path d="M190 190 V58" stroke={RED} strokeWidth={8} {...SW} style={{ transform: `rotate(${(spin * 3600).toFixed(1)}deg)`, transformOrigin: "190px 190px" }} />
          <circle cx={190} cy={190} r={14} fill={INK} />
        </svg>
      </div>
      {/* moedas: a pilha cai e as moedas escapam para fora do quadro */}
      <div style={{ position: "absolute", left: 600, top: 860, width: 340, height: 360, opacity: coinsIn * (1 - sceneBOut), transform: `scale(${(0.5 + 0.5 * coinsIn).toFixed(3)}) translateX(${(sceneBOut * 120).toFixed(1)}px)` }}>
        {Array.from({ length: 6 }).map((_, i) => {
          const fly = interpolate(t, [2.75 + i * 0.16, 3.6 + i * 0.16], [0, 1], { ...cl, easing: Easing.in(Easing.quad) });
          const left = i % 2 ? 1 : -1;
          return (
            <div key={i} style={{ position: "absolute", left: 70, top: 270 - i * 44, width: 200, height: 60, borderRadius: "50%", background: TEAL_L, border: `10px solid ${TEAL}`, boxSizing: "border-box", transform: `translate(${(fly * left * (260 + i * 30)).toFixed(1)}px, ${(fly * (-120 - i * 40) + fly * fly * 700).toFixed(1)}px) rotate(${(fly * left * 160).toFixed(1)}deg)`, opacity: 1 - lin(t, 3.4 + i * 0.16, 3.7 + i * 0.16) }} />
          );
        })}
      </div>

      {/* C · licença vencida */}
      <Lines t={t} items={[["tentando renovar", 4.03], ["suas licenças", 5.15, true]]} size={104} top={330} />
      <div style={{ position: "absolute", left: 540 - 300, top: 760, width: 600, height: 760 }}>
        {[-1, 1].map((s, i) => (
          <div key={i} style={{ position: "absolute", inset: 0, borderRadius: 34, background: WHITE, boxShadow: SHADOW, opacity: docs, transform: `translateY(${((1 - docs) * 300).toFixed(1)}px) rotate(${(s * 7 * docs).toFixed(2)}deg) translateX(${(s * 40 * docs).toFixed(1)}px)` }} />
        ))}
        <div style={{ position: "absolute", inset: 0, borderRadius: 34, background: WHITE, boxShadow: SHADOW, opacity: k(t, 4.25, 0.5), transform: `translateY(${((1 - k(t, 4.25, 0.6)) * 380).toFixed(1)}px) rotate(${(interpolate(t, [4.25, 6.6], [-3, 1.5], cl)).toFixed(2)}deg)`, padding: 60, boxSizing: "border-box" }}>
          <div style={{ fontFamily: F, fontWeight: 700, fontSize: 52, letterSpacing: "0.12em", color: INK }}>LICENÇA</div>
          <div style={{ height: 8, width: 120, background: TEAL, borderRadius: 4, marginTop: 18 }} />
          {[420, 470, 360, 450, 300, 400].map((w, i) => (
            <div key={i} style={{ height: 22, width: w, background: LINE, borderRadius: 11, marginTop: i === 0 ? 50 : 28 }} />
          ))}
          {/* carimbo */}
          <div style={{ position: "absolute", left: 120, top: 470, width: 360, height: 140, border: `10px solid ${RED}`, borderRadius: 22, display: "flex", alignItems: "center", justifyContent: "center", fontFamily: F, fontWeight: 700, fontSize: 64, letterSpacing: "0.08em", color: RED, opacity: Math.min(1, stamp * 1.5), transform: `rotate(-12deg) scale(${(2.2 - 1.2 * stamp).toFixed(3)})`, background: "rgba(255,255,255,0.75)" }}>
            VENCIDA
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

// ───────── 2 · nós fazemos isso por você (verde cheio) ─────────
const PorVoce: React.FC<{ t: number }> = ({ t }) => {
  const card = k(t, T2 - 0.1, 0.6);
  const ok = pop(t, 8.2, 0.45);
  return (
    <AbsoluteFill style={{ background: TEAL }}>
      <Lines t={t} items={[["Nós fazemos", 6.88], ["isso por você.", 7.62]]} size={116} top={300} color={WHITE} weight={600} />
      <div style={{ position: "absolute", left: 540 - 270, top: 820, width: 540, height: 680, borderRadius: 34, background: WHITE, boxShadow: "0 40px 90px rgba(0,30,28,0.35)", padding: 56, boxSizing: "border-box", opacity: card, transform: `translateY(${((1 - card) * 200).toFixed(1)}px) rotate(${interpolate(t, [T2, T3], [2.5, -1.5], cl).toFixed(2)}deg)` }}>
        <div style={{ fontFamily: F, fontWeight: 700, fontSize: 46, letterSpacing: "0.12em", color: INK }}>LICENÇA</div>
        <div style={{ height: 8, width: 110, background: TEAL, borderRadius: 4, marginTop: 16 }} />
        {[380, 420, 320, 400, 260].map((w, i) => (
          <div key={i} style={{ height: 20, width: w, background: LINE, borderRadius: 10, marginTop: i === 0 ? 44 : 26 }} />
        ))}
        <div style={{ position: "absolute", left: 270 - 120, top: 380, width: 240, height: 240, borderRadius: "50%", background: TEAL, display: "flex", alignItems: "center", justifyContent: "center", transform: `scale(${ok.toFixed(3)})`, boxShadow: "0 18px 40px rgba(14,93,88,0.35)" }}>
          <svg viewBox="0 0 120 120" width={150} height={150}>
            <path d="M28 62 L52 86 L94 36" stroke={WHITE} strokeWidth={14} pathLength={1} {...SW} style={draw(t, 8.32, 0.4)} />
          </svg>
        </div>
      </div>
    </AbsoluteFill>
  );
};

// ───────── 3 · a marca e a especialidade ─────────
// logo.png: 1875×850 (5× o arquivo do cliente); o globo fica em x 370–784, y 170–599 do arquivo
const LOGO_W = 1875, LOGO_H = 850;
const Logo: React.FC<{ width: number; t: number; at: number }> = ({ width, t, at }) => {
  const s = width / LOGO_W;
  const e = k(t, at + 0.25, 0.55);
  const g = interpolate(t, [at, at + 0.7], [0, 1], { ...cl, easing: OUT });
  // o globo chega girando e grande, pousa no lugar dele no logo; o resto do logo se revela da esquerda para a direita
  const gx = 370 * s, gy = 170 * s, gw = 414 * s, gh = 429 * s;
  return (
    <div style={{ position: "relative", width, height: LOGO_H * s }}>
      <Img src={staticFile("solution/logo.png")} style={{ position: "absolute", left: 0, top: 0, width, height: LOGO_H * s, opacity: e, clipPath: `inset(0 ${((1 - e) * 100).toFixed(2)}% 0 0)`, filter: `blur(${((1 - e) * 10).toFixed(1)}px)` }} />
      <Img src={staticFile("solution/globo.png")} style={{ position: "absolute", left: gx, top: gy, width: gw, height: gh, opacity: Math.min(1, g * 2) * (1 - e), transform: `scale(${(2.6 - 1.6 * g).toFixed(3)}) rotate(${((1 - g) * -220).toFixed(1)}deg)` }} />
    </div>
  );
};
const Marca: React.FC<{ t: number; mun?: boolean }> = ({ t, mun = false }) => {
  const up = io(t, 10.45, 11.1);
  const e1 = pop(t, 12.85, 0.5), e2 = pop(t, 13.65, 0.5);
  return (
    <AbsoluteFill style={{ background: PAPER }}>
      <div style={{ position: "absolute", left: 0, right: 0, top: interpolate(up, [0, 1], [700, 170]), display: "flex", justifyContent: "center", transform: `scale(${(1 - 0.3 * up).toFixed(3)})` }}>
        <Logo width={880} t={t} at={9.0} />
      </div>
      <Lines t={t} items={[["especializada em", 10.95]]} size={54} top={650} color={MUTED} weight={500} />
      <Lines t={t} items={[["Renovação", 11.73], ["de licenças", 12.36, true]]} size={124} top={740} />
      {/* v3 (pedido, 14/10): "municipais, estaduais e federais" em três faixas, uma por batida */}
      {mun ? (
        <div style={{ position: "absolute", left: 120, right: 120, top: 1090, display: "flex", flexDirection: "column", gap: 30 }}>
          {[
            { e: pop(t, 12.45, 0.5), label: "Municipais", icon: <path d="M12 110 H108 M20 110 V52 H50 V110 M50 110 V22 H84 V110 M84 110 V66 H100 V110 M30 66 H40 M30 82 H40 M60 38 H74 M60 56 H74 M60 74 H74" stroke={TEAL} strokeWidth={9} {...SW} /> },
            { e: pop(t, 12.91, 0.5), label: "Estaduais", icon: <path d="M60 18 C38 18 22 34 22 56 C22 84 60 116 60 116 C60 116 98 84 98 56 C98 34 82 18 60 18 Z M60 42 a14 14 0 1 0 0.1 0" stroke={TEAL} strokeWidth={9} {...SW} /> },
            { e: pop(t, 13.73, 0.5), label: "Federais", icon: <path d="M16 46 L60 18 L104 46 Z M26 56 V96 M48 56 V96 M72 56 V96 M94 56 V96 M14 108 H106" stroke={TEAL} strokeWidth={9} {...SW} /> },
          ].map((c, i) => (
            <div key={i} style={{ height: 136, borderRadius: 34, background: WHITE, boxShadow: SHADOW, display: "flex", alignItems: "center", justifyContent: "center", gap: 30, opacity: Math.min(1, c.e * 1.5), transform: `translateX(${((1 - c.e) * (i % 2 ? 260 : -260)).toFixed(1)}px) scale(${(0.8 + 0.2 * c.e).toFixed(3)})` }}>
              <svg viewBox="0 0 120 130" width={84} height={92}>{c.icon}</svg>
              <div style={{ fontFamily: F, fontWeight: 600, fontSize: 64, letterSpacing: "-0.02em", color: INK, width: 340 }}>{c.label}</div>
            </div>
          ))}
        </div>
      ) : (
      <div style={{ position: "absolute", left: 120, right: 120, top: 1140, display: "flex", gap: 40, justifyContent: "center" }}>
        {[
          { e: e1, label: "Estaduais", icon: <path d="M60 18 C38 18 22 34 22 56 C22 84 60 116 60 116 C60 116 98 84 98 56 C98 34 82 18 60 18 Z M60 42 a14 14 0 1 0 0.1 0" stroke={TEAL} strokeWidth={9} {...SW} /> },
          { e: e2, label: "Federais", icon: <path d="M16 46 L60 18 L104 46 Z M26 56 V96 M48 56 V96 M72 56 V96 M94 56 V96 M14 108 H106" stroke={TEAL} strokeWidth={9} {...SW} /> },
        ].map((c, i) => (
          <div key={i} style={{ width: 400, height: 330, borderRadius: 34, background: WHITE, boxShadow: SHADOW, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 22, opacity: Math.min(1, c.e * 1.5), transform: `translateY(${((1 - c.e) * 140).toFixed(1)}px) scale(${(0.7 + 0.3 * c.e).toFixed(3)})` }}>
            <svg viewBox="0 0 120 130" width={120} height={130}>{c.icon}</svg>
            <div style={{ fontFamily: F, fontWeight: 600, fontSize: 60, letterSpacing: "-0.02em", color: INK }}>{c.label}</div>
          </div>
        ))}
      </div>
      )}
    </AbsoluteFill>
  );
};

// ───────── 4 · os serviços, um por batida ─────────
const ServCard: React.FC<{ t: number; a: number; b: number | null; icon: React.ReactNode; lines: string[]; drawAt: number }> = ({ t, a, b, icon, lines, drawAt }) => {
  const inn = interpolate(t, [a - 0.1, a + 0.4], [0, 1], { ...cl, easing: OUT });
  const out = b === null ? 0 : interpolate(t, [b - 0.1, b + 0.35], [0, 1], { ...cl, easing: Easing.in(Easing.cubic) });
  if (inn <= 0 || out >= 1) return null;
  const x = (1 - inn) * 1000 - out * 1100;
  const r = (1 - inn) * 9 - out * 9;
  const life = lin(t, a, b ?? 21.9);
  return (
    <div style={{ position: "absolute", left: 120, top: 520, width: 840, height: 900, borderRadius: 44, background: WHITE, boxShadow: SHADOW, transform: `translateX(${x.toFixed(1)}px) rotate(${r.toFixed(2)}deg) scale(${(0.97 + 0.07 * life).toFixed(4)})`, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 50 }}>
      <div style={{ width: 360, height: 360, borderRadius: "50%", background: TEAL_L, display: "flex", alignItems: "center", justifyContent: "center", transform: `scale(${pop(t, a + 0.1, 0.5).toFixed(3)})` }}>
        <svg viewBox="0 0 200 200" width={230} height={230} style={{ overflow: "visible" }}>
          <g style={draw(t, drawAt, 0.7)}>{icon}</g>
        </svg>
      </div>
      <div style={{ textAlign: "center" }}>
        <div style={{ fontFamily: F, fontWeight: 500, fontSize: 64, color: MUTED, letterSpacing: "-0.02em", ...blurIn(t, a + 0.15) }}>{lines[0]}</div>
        {lines.slice(1).map((l, i) => (
          <div key={i} style={{ fontFamily: F, fontWeight: 700, fontSize: 84, color: INK, letterSpacing: "-0.03em", lineHeight: 1.1, ...blurIn(t, a + 0.3 + i * 0.12) }}>{l}</div>
        ))}
      </div>
    </div>
  );
};
const Servicos: React.FC<{ t: number; mun?: boolean }> = ({ t, mun = false }) => {
