          <path d="M84 70 L150 30" {...P} />
          <path d="M70 176 L94 140" {...P} />
        </>} />
      {/* "e PLG": selo que encosta no cartão das mineradoras */}
      <div style={{ position: "absolute", left: 540 - 170, top: 1470, width: 340, height: 130, borderRadius: 65, background: TEAL, display: "flex", alignItems: "center", justifyContent: "center", fontFamily: F, fontWeight: 700, fontSize: 70, letterSpacing: "0.02em", color: WHITE, transform: `scale(${plg.toFixed(3)}) rotate(${((1 - plg) * -12).toFixed(1)}deg)`, boxShadow: "0 18px 40px rgba(14,93,88,0.3)" }}>
        + PLG
      </div>
    </AbsoluteFill>
  );
};

// ───────── 5 · projeto de combate a incêndio e o processo do início ao fim ─────────
const Incendio: React.FC<{ t: number }> = ({ t }) => {
  const planOut = io(t, 24.35, 24.85);
  const tl = k(t, 24.6, 0.5);
  const run = interpolate(t, [24.9, 27.35], [0, 1], { ...cl, easing: Easing.bezier(0.4, 0, 0.2, 1) });
  const done = pop(t, 27.35, 0.4);
