export const Solution: React.FC<{ municipais?: boolean; warp?: [number, number][] }> = ({ municipais = false, warp }) => {
  const tNew = useCurrentFrame() / SLT_FPS - LEAD;
  const t = warp ? interpolate(tNew, warp.map((p) => p[0]), warp.map((p) => p[1]), cl) : tNew;
  // trocas, cada uma de um jeito: círculo verde que nasce do carimbo · íris branca do centro · empurrão lateral ·
  // faixa inclinada · folha verde que sobe · círculo que fecha no telefone
  const c2 = interpolate(t, [T2 - 0.25, T2 + 0.3], [0, 1], { ...cl, easing: INOUT });
  const c3 = interpolate(t, [T3 - 0.22, T3 + 0.25], [0, 1], { ...cl, easing: INOUT });
  const push = interpolate(t, [T4 - 0.26, T4 + 0.22], [0, 1], { ...cl, easing: INOUT });
  const band = interpolate(t, [T5 - 0.3, T5 + 0.3], [0, 1], { ...cl, easing: INOUT });
  const sheet = interpolate(t, [T6 - 0.28, T6 + 0.22], [0, 1], { ...cl, easing: OUT });
  const c7 = interpolate(t, [T7 - 0.22, T7 + 0.3], [0, 1], { ...cl, easing: INOUT });
  // abertura: a câmera chega de perto em batida rápida e segue derivando
  const hit = interpolate(t, [-0.15, 0.5], [1.4, 1], { ...cl, easing: OUT });
  const hitR = interpolate(t, [-0.15, 0.5], [-5, 0], { ...cl, easing: OUT });
  return (
    <AbsoluteFill style={{ background: PAPER }}>
      {t < T2 + 0.35 ? (
        <AbsoluteFill style={{ transform: `scale(${hit.toFixed(4)}) rotate(${hitR.toFixed(2)}deg)` }}>
          <Cam t={t} a={0} b={T2} from={[1, 0, 0]} to={[1.12, 0, -60]} hits={[2.37, 5.62]}><Abertura t={t} /></Cam>
        </AbsoluteFill>
      ) : null}
      {t >= T2 - 0.27 && t < T3 + 0.3 ? (
        <AbsoluteFill style={{ clipPath: t < T2 + 0.35 ? `circle(${(c2 * 2300).toFixed(0)}px at 540px 1140px)` : undefined }}>
          <Cam t={t} a={T2} b={T3} from={[1.12, 0, 40]} to={[1, 0, -30]} hits={[8.25]}><PorVoce t={t} /></Cam>
        </AbsoluteFill>
      ) : null}
      {t >= T3 - 0.24 && t < T4 + 0.25 ? (
        <AbsoluteFill style={{ clipPath: t < T3 + 0.3 ? `circle(${(c3 * 2300).toFixed(0)}px at 540px 900px)` : undefined, transform: `translateX(${(-push * 1080).toFixed(1)}px)` }}>
