        </AbsoluteFill>
      ) : null}
      {t >= T4 - 0.28 && t < T5 + 0.32 ? (
        <AbsoluteFill style={{ transform: `translateX(${((1 - push) * 1080).toFixed(1)}px)` }}>
          <Cam t={t} a={T4} b={T5} from={[1, -40, 0]} to={[1.1, 40, 30]} hits={[20.98]}><Servicos t={t} mun={municipais} /></Cam>
        </AbsoluteFill>
      ) : null}
      {t >= T5 - 0.02 && t < T6 + 0.25 ? (
        <AbsoluteFill style={{ transform: `scale(${(1 - 0.06 * sheet).toFixed(4)})` }}>
          <Cam t={t} a={T5} b={T6} from={[1.1, -40, 0]} to={[1, 40, 0]} hits={[23.14, 27.41]}><Incendio t={t} /></Cam>
        </AbsoluteFill>
      ) : null}
      {t >= T5 - 0.32 && t < T5 + 0.32 ? (
        <div style={{ position: "absolute", left: 540 - 1000, top: -500, width: 2000, height: 2920, background: TEAL, transform: `rotate(18deg) translateX(${((band - 0.5) * 2 * 2700).toFixed(1)}px)` }} />
      ) : null}
      {t >= T6 - 0.3 && t < T7 + 0.32 ? (
        <AbsoluteFill style={{ transform: `translateY(${((1 - sheet) * 1920).toFixed(1)}px)`, borderRadius: `${((1 - sheet) * 90).toFixed(0)}px ${((1 - sheet) * 90).toFixed(0)}px 0 0`, overflow: "hidden" }}>
          <Cam t={t} a={T6} b={T7} from={[1, 0, -40]} to={[1.1, 0, 30]} hits={[28.94, 32.35]}><Telefone t={t} /></Cam>
        </AbsoluteFill>
      ) : null}
      {t >= T7 - 0.24 ? (
        <AbsoluteFill style={{ clipPath: `circle(${(c7 * 2300).toFixed(0)}px at 540px 1000px)` }}>
          <Cam t={t} a={T7} b={38.9} from={[1.16, 0, 0]} to={[1, 0, -20]} hits={[35.25]}><Fecho t={t} /></Cam>
        </AbsoluteFill>
      ) : null}
    </AbsoluteFill>
  );
};

